import {CalendarIcon} from '@sanity/icons/Calendar'
import {CheckmarkIcon} from '@sanity/icons/Checkmark'
import {ClockIcon} from '@sanity/icons/Clock'
import {CropIcon} from '@sanity/icons/Crop'
import {DownloadIcon} from '@sanity/icons/Download'
import {EditIcon} from '@sanity/icons/Edit'
import {ErrorOutlineIcon} from '@sanity/icons/ErrorOutline'
import {RevertIcon} from '@sanity/icons/Revert'
import {RobotIcon} from '@sanity/icons/Robot'
import {SearchIcon} from '@sanity/icons/Search'
import {SyncIcon} from '@sanity/icons/Sync'
import {TagIcon} from '@sanity/icons/Tag'
import {TrashIcon} from '@sanity/icons/Trash'
import {
  Button,
  Card,
  Dialog,
  Flex,
  Heading,
  Spinner,
  Stack,
  Tab,
  TabList,
  TabPanel,
  Text,
  TextInput,
} from '@sanity/ui'
import {type InputEvent, useEffect, useRef, useState} from 'react'

import {DIALOGS_Z_INDEX} from '../../util/constants'
import {isCaptionTrack} from '../../util/tracks'
import type {MuxAudioTrack, MuxPlaybackId, PlaybackPolicy} from '../../util/types'
import AudioTracksManager from '../AudioTracksManager'
import DownloadAssetDialog from '../DownloadAssetDialog'
import FormField from '../FormField'
import IconInfo from '../IconInfo'
import {ResolutionIcon} from '../icons/Resolution'
import {StopWatchIcon} from '../icons/StopWatch'
import Mezzanine from '../Mezzanine'
import {RobotsErrorBoundary} from '../robots/RobotsErrorBoundary'
import {RobotsPanel} from '../robots/RobotsPanel'
import TextTracksManager from '../TextTracksManager'
import VideoPlayer from '../VideoPlayer'
import DeleteDialog from './DeleteDialog'
import useVideoDetails, {type VideoDetailsProps} from './useVideoDetails'
import VideoReferences from './VideoReferences'

const AssetInput: React.FC<{
  label: string
  description?: string
  placeholder?: string
  value: string
  onInput: (e: InputEvent<HTMLInputElement>) => void
  disabled?: boolean
}> = (props) => (
  <FormField title={props.label} description={props.description} inputId={props.label}>
    <TextInput
      id={props.label}
      value={props.value}
      placeholder={props.placeholder}
      onInput={props.onInput}
      disabled={props.disabled}
    />
  </FormField>
)

const VideoDetails: React.FC<VideoDetailsProps> = (props) => {
  const [tab, setTab] = useState<'details' | 'references' | 'robots'>('details')
  const {
    displayInfo,
    filename,
    modified,
    references,
    referencesLoading,
    setFilename,
    state,
    setState,
    handleClose,
    confirmClose,
    saveChanges,
    handleResync,
    isResyncing,
  } = useVideoDetails(props)

  const isSaving = state === 'saving'

  // Avoid layout shifts in large screens' 2-column dialog by setting their `minHeight` to the container's
  const [containerHeight, setContainerHeight] = useState<number | null>(null)
  const contentsRef = useRef<HTMLDivElement>(null)
  useEffect(() => {
    if (!contentsRef.current || !('getBoundingClientRect' in contentsRef.current)) return

    setContainerHeight(contentsRef.current.getBoundingClientRect().height)
  }, [])

  return (
    <Dialog
      animate
      header={displayInfo.title}
      zOffset={DIALOGS_Z_INDEX}
      id="video-details-dialog"
      onClose={handleClose}
      onClickOutside={handleClose}
      width={2}
      position="fixed"
      footer={
        <Card padding={3}>
          <Flex justify="space-between" align="center">
            <Flex gap={2}>
              <Button
                icon={TrashIcon}
                fontSize={2}
                padding={3}
                mode="bleed"
                text="Delete"
                tone="critical"
                onClick={() => setState('deleting')}
                disabled={isSaving || isResyncing}
              />
              <Button
                icon={SyncIcon}
                fontSize={2}
                padding={3}
                mode="bleed"
                text="Resync"
                tone="primary"
                onClick={handleResync}
                disabled={isSaving || isResyncing}
                iconRight={isResyncing && Spinner}
              />
            </Flex>
            <Flex gap={2}>
              <Button
                icon={DownloadIcon}
                fontSize={2}
                padding={3}
                mode="bleed"
                text="Download"
                tone="default"
                onClick={() => setState('downloading')}
                disabled={isSaving}
              />
              {modified && (
                <Button
                  icon={CheckmarkIcon}
                  fontSize={2}
                  padding={3}
                  mode="ghost"
                  text="Save and close"
                  tone="positive"
                  onClick={saveChanges}
                  iconRight={isSaving && Spinner}
                  disabled={isSaving || isResyncing}
                />
              )}
            </Flex>
          </Flex>
        </Card>
      }
    >
      {/* DELETION DIALOG */}
      {state === 'deleting' && (
        <DeleteDialog
          asset={props.asset}
          cancelDelete={() => setState('idle')}
          referencesLoading={referencesLoading}
          references={references}
          succeededDeleting={() => {
            props.closeDialog()
          }}
        />
      )}

      {state === 'downloading' && (
        <DownloadAssetDialog asset={props.asset} onClose={() => setState('idle')} absolute />
      )}

      {/* CONFIRM CLOSING DIALOG */}
      {state === 'closing' && (
        <Dialog
          animate
          header={'You have unsaved changes'}
          zOffset={DIALOGS_Z_INDEX}
          id="closing-video-details-dialog"
          onClose={() => confirmClose(false)}
          onClickOutside={() => confirmClose(false)}
          width={1}
          position="fixed"
          footer={
            <Card padding={3}>
              <Flex justify="space-between" align="center">
                <Button
                  icon={ErrorOutlineIcon}
                  fontSize={2}
                  padding={3}
                  text="Discard changes"
                  tone="critical"
                  onClick={() => confirmClose(true)}
                />
                {modified && (
                  <Button
                    icon={RevertIcon}
                    fontSize={2}
                    padding={3}
                    mode="ghost"
                    text="Keep editing"
                    tone="primary"
                    onClick={() => confirmClose(false)}
                  />
                )}
              </Flex>
            </Card>
          }
        >
          <Card padding={5}>
            <Stack style={{textAlign: 'center'}} gap={3}>
              <Heading size={2}>Unsaved changes will be lost</Heading>
              <Text size={2}>Are you sure you want to discard them?</Text>
            </Stack>
          </Card>
        </Dialog>
      )}
      <Card
        padding={4}
        sizing="border"
        style={{
          containerType: 'inline-size',
        }}
      >
        <Flex
          sizing="border"
          gap={4}
          direction={['column', 'column', 'row']}
          align="flex-start"
          ref={contentsRef}
          style={
            typeof containerHeight === 'number'
              ? {
                  minHeight: containerHeight,
                }
              : undefined
          }
        >
          <Stack gap={4} flex={1} sizing="border">
            <VideoPlayer asset={props.asset} autoPlay={props.asset.autoPlay || false} />
            {/* Kept on the Robots tab too, so the captions stay in view while a job runs. */}
            {tab !== 'references' && (
              <>
                <TextTracksManager
                  asset={props.asset}
                  iconOnly
                  collapseTracks
                  tracks={
                    displayInfo?.text_tracks ||
                    props.asset.data?.tracks?.filter(isCaptionTrack) ||
                    []
                  }
                />
                <AudioTracksManager
                  asset={props.asset}
                  iconOnly
                  collapseTracks
                  tracks={
                    displayInfo?.audio_tracks ||
                    props.asset.data?.tracks?.filter(
                      (track): track is MuxAudioTrack => track.type === 'audio',
                    ) ||
                    []
                  }
                />
                <Mezzanine asset={props.asset} />
              </>
            )}
          </Stack>
          <Stack gap={4} flex={1} sizing="border">
            <TabList gap={2}>
              <Tab
                aria-controls="details-panel"
                icon={EditIcon}
                id="details-tab"
                label="Details"
                onClick={() => setTab('details')}
                selected={tab === 'details'}
              />
              <Tab
                aria-controls="robots-panel"
                icon={RobotIcon}
                id="robots-tab"
                label="Robots"
                onClick={() => setTab('robots')}
                selected={tab === 'robots'}
              />
              <Tab
                aria-controls="references-panel"
                icon={SearchIcon}
                id="references-tab"
                label={`Used by ${references ? `(${references.length})` : ''}`}
                onClick={() => setTab('references')}
                selected={tab === 'references'}
              />
            </TabList>
            <TabPanel
              aria-labelledby="details-tab"
              id="details-panel"
              hidden={tab !== 'details'}
              style={{wordBreak: 'break-word'}}
            >
              <Stack gap={4}>
                <AssetInput
                  label="Video title or file name"
                  description="Not visible to users. Useful for finding videos later."
                  value={filename || ''}
                  onInput={(e) => setFilename(e.currentTarget.value)}
                  disabled={state !== 'idle'}
                />
                <Stack gap={3}>
                  {displayInfo?.duration && (
                    <IconInfo
                      text={`Duration: ${displayInfo.duration}`}
                      icon={ClockIcon}
                      size={2}
                    />
                  )}
                  {displayInfo?.max_stored_resolution && (
                    <IconInfo
                      text={`Max Resolution: ${displayInfo.max_stored_resolution}`}
                      icon={ResolutionIcon}
                      size={2}
                    />
                  )}
                  {displayInfo?.max_stored_frame_rate && (
                    <IconInfo
                      text={`Frame rate: ${displayInfo.max_stored_frame_rate}`}
                      icon={StopWatchIcon}
                      size={2}
                    />
                  )}
                  {displayInfo?.aspect_ratio && (
                    <IconInfo
                      text={`Aspect Ratio: ${displayInfo.aspect_ratio}`}
                      icon={CropIcon}
                      size={2}
                    />
                  )}
                  <IconInfo
                    text={`Uploaded on: ${displayInfo.createdAt.toLocaleDateString('en', {
                      year: 'numeric',
                      month: '2-digit',
                      day: '2-digit',
                      hour: '2-digit',
                      minute: '2-digit',
                      hour12: true,
                    })}`}
                    icon={CalendarIcon}
                    size={2}
                  />
                  <IconInfo text={`Mux ID: \n${displayInfo.id}`} icon={TagIcon} size={2} />
                  <PlaybackIds playback_ids={displayInfo.playback_ids} />
                </Stack>
              </Stack>
            </TabPanel>
            <TabPanel
              aria-labelledby="references-tab"
              id="references-panel"
              hidden={tab !== 'references'}
            >
              <VideoReferences references={references} isLoaded={!referencesLoading} />
            </TabPanel>
            <TabPanel aria-labelledby="robots-tab" id="robots-panel" hidden={tab !== 'robots'}>
              {tab === 'robots' && (
                <RobotsErrorBoundary>
                  <RobotsPanel asset={props.asset} config={props.config} />
                </RobotsErrorBoundary>
              )}
            </TabPanel>
          </Stack>
        </Flex>
      </Card>
    </Dialog>
  )
}

const PlaybackIds = ({playback_ids}: {playback_ids?: MuxPlaybackId[]}) => {
  if (playback_ids) {
    return playback_ids.map((entry) => (
      <IconInfo
        key={entry.id}
        text={`Playback ID [${policyToText(entry.policy)}]: ${entry.id}`}
        icon={TagIcon}
        size={2}
      />
    ))
  }
  return <IconInfo text={'No Playback ID'} icon={TagIcon} size={2} />
}

const policyToText = (policy: PlaybackPolicy) => {
  switch (policy) {
    case 'drm':
      return 'DRM'
    case 'signed':
      return 'Signed'
    case 'public':
      return 'Public'
    default:
      return policy
  }
}
export default VideoDetails
